        flex: 0 0 auto;
      }

      .card {
        padding: 2rem;
      }

      .card h2 {
        margin: 0;
        font-size: 1.4rem;
      }

      form {
        display: grid;
        gap: 1.25rem;
        margin-top: 1.5rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
