      input {
        width: 100%;
        padding: 0.95rem 1rem;
        border: 1px solid var(--panel-border);
        border-radius: 0.9rem;
        background: #ffffff;
        color: var(--text);
        font: inherit;
        transition: border-color 160ms ease, box-shadow 160ms ease;
      }

      input::placeholder {
        color: #6b7280;
      }

      input:focus {
        outline: 3px solid rgba(36, 87, 255, 0.18);
