        border-color: var(--error);
        background: var(--error-bg);
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .field-error {
        margin: 0;
        color: var(--error);
        font-size: 0.95rem;
        font-weight: 600;
      }

      .success-banner {
        margin: 0 0 1rem;
        padding: 0.875rem 1rem;
        border-radius: 0.9rem;
        background: #ecfdf3;
        color: #166534;
        font-weight: 600;
      }

      .actions {
        display: flex;
        align-items: center;
        gap: 0.75rem;
        flex-wrap: wrap;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.4rem;
        background: linear-gradient(135deg, var(--primary), #5b7cfa);
        color: #ffffff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
        box-shadow: 0 16px 32px rgba(36, 87, 255, 0.24);
      }

      button:hover {
        transform: translateY(-1px);
      }

      button:focus {
        outline: 3px solid rgba(36, 87, 255, 0.22);
        outline-offset: 2px;
      }

      button:active {
        transform: translateY(0);
      }

      @media (max-width: 840px) {
