  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content"></main>
    <script>
      (() => {
        const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        const PHONE_PATTERN = /^\+?[0-9()\-\s]{7,20}$/;

        const root = document.getElementById("main-content");
        const state = {
          values: {
            fullName: "",
            email: "",
            phone: ""
          },
          errors: {},
          submitted: false
        };

        const escapeHtml = (value) =>
          value
            .replaceAll("&", "&amp;")
            .replaceAll("<", "&lt;")
            .replaceAll(">", "&gt;")
            .replaceAll('"', "&quot;")
            .replaceAll("'", "&#39;");

        const validate = (values) => {
          const errors = {};

          if (!values.fullName.trim()) {
            errors.fullName = "Enter your full name.";
          }

          if (!values.email.trim()) {
            errors.email = "Enter your email address.";
          } else if (!EMAIL_PATTERN.test(values.email.trim())) {
            errors.email = "Enter a valid email address.";
          }

          if (values.phone.trim() && !PHONE_PATTERN.test(values.phone.trim())) {
            errors.phone = "Enter a valid phone number using digits, spaces, parentheses, or hyphens.";
          }

          return errors;
        };

        const Field = ({
          id,
          name,
          label,
          type,
          autocomplete,
          required,
          value,
          error,
          helperText,
          placeholder
        }) => {
          const helperId = helperText ? id + "-hint" : "";
          const errorId = error ? id + "-error" : "";
          const describedBy = [helperId, errorId].filter(Boolean).join(" ");

          return `
            <div class="form-field">
              <label for="${id}">
                ${label}${required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
              </label>
              <input
                id="${id}"
                name="${name}"
                type="${type}"
                autocomplete="${autocomplete}"
                ${required ? "required" : ""}
                ${describedBy ? `aria-describedby="${describedBy}"` : ""}
                aria-invalid="${error ? "true" : "false"}"
                value="${escapeHtml(value)}"
                placeholder="${placeholder ? escapeHtml(placeholder) : ""}"
              />
              ${helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : ""}
              ${error ? `<p class="field-error" id="${errorId}">${error}</p>` : ""}
            </div>
          `;
        };

        const ContactForm = () => {
          const { values, errors, submitted } = state;

          return `
            <section class="shell" aria-labelledby="support-title">
              <section class="hero" aria-label="Support overview">
                <div>
                  <span class="eyebrow">Support</span>
                  <h1 id="support-title">Talk to our support team</h1>
                  <p>
                    Share your question and we will route it to the right specialist. We typically reply
                    with the next best step and any follow-up details you need.
                  </p>
                </div>
                <ul class="feature-list" aria-label="Support benefits">
                  <li>Get help with onboarding, billing, and product guidance.</li>
                  <li>Receive clear next steps from a real support specialist.</li>
                  <li>Leave a phone number if you would like us to call you back.</li>
                </ul>
              </section>
              <section class="card" aria-labelledby="contact-form-title">
                <h2 id="contact-form-title">Send a message</h2>
                <p class="card-intro">Required fields are marked with an asterisk.</p>
                ${
                  submitted && Object.keys(errors).length === 0
                    ? '<p class="success-banner" aria-live="polite">Thanks. Your support request is ready to send.</p>'
                    : ""
                }
                <form id="support-form" novalidate>
                  <p class="required-note">Please complete the required fields before submitting.</p>
                  ${Field({
                    id: "full-name",
                    name: "fullName",
                    label: "Full name",
                    type: "text",
                    autocomplete: "name",
                    required: true,
                    value: values.fullName,
                    error: errors.fullName,
                    placeholder: "Jordan Lee"
                  })}
                  ${Field({
                    id: "email-address",
                    name: "email",
                    label: "Email address",
                    type: "email",
                    autocomplete: "email",
                    required: true,
                    value: values.email,
                    error: errors.email,
                    placeholder: "jordan@example.com"
                  })}
                  ${Field({
                    id: "phone-number",
                    name: "phone",
                    label: "Phone number",
                    type: "tel",
                    autocomplete: "tel",
                    required: false,
                    value: values.phone,
                    error: errors.phone,
                    helperText: "Optional. Use digits with spaces, hyphens, or parentheses, for example (555) 123-4567.",
                    placeholder: "(555) 123-4567"
                  })}
                  <div class="actions">
                    <button type="submit">Submit</button>
                  </div>
                </form>
              </section>
            </section>
          `;
        };

        const App = () => ContactForm();

        const render = () => {
          root.innerHTML = App();

          const form = document.getElementById("support-form");
          const inputs = form.querySelectorAll("input");

          inputs.forEach((input) => {
            input.addEventListener("input", (event) => {
              const { name, value } = event.target;
              state.values[name] = value;
              state.errors = validate(state.values);
              render();
            });
          });

          form.addEventListener("submit", (event) => {
            event.preventDefault();
            state.submitted = true;
            state.errors = validate(state.values);
            render();

            const firstInvalid = document.querySelector('[aria-invalid="true"]');
            if (firstInvalid) {
              firstInvalid.focus();
            }
          });
        };

        render();
      })();
    </script>
  </body>
</html>
